export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
/** A bed, both halves: foot at [x,y,z], the head one step toward facing (the pillow end), same colour and facing.
 *  Both cells must be air (a bed never replaces a wall block); the head goes against a solid wall, never a window or
 *  a door. Returns true when placed, false (placing nothing) when a cell is taken. */
export const bed = (g, [x, y, z], facing, color = "red") => {
  const [dx, dz] = STEP[facing] ?? STEP.north, b = `${color}_bed`, free = (x, y, z) => !g.get(x, y, z) || /(^|_)air$/.test(g.get(x, y, z).block);
  if (!free(x, y, z) || !free(x + dx, y, z + dz)) return false;
  g.set(x, y, z, b, { facing, part: "foot", occupied: "false" });
  g.set(x + dx, y, z + dz, b, { facing, part: "head", occupied: "false" });
  return true;
};
/** A straight flight of stairs a player walks up without jumping: from = the first step's cell (standing on the lower
 *  floor), facing = the way you walk up, to = the y of the UPPER FLOOR's own block layer. The last step is set in that
 *  layer, flush with the floor you step out onto, so a storey of h (floor to floor) takes h steps. Clears 2 blocks of
 *  headroom over every step (cutting the floor above where the flight passes) and hangs an upside-down stair under each
 *  step as a stringer. width runs to the right of facing. Returns { steps, landing: [x,y,z] (feet on the upper floor), notes }. */
export const flight = (g, { from: [x, y, z], facing, to, material = "oak", width = 1, stringer = true }) => {
  const [dx, dz] = STEP[facing] ?? STEP.north, [rx, rz] = [-dz, dx], OPP = { north: "south", south: "north", east: "west", west: "east" }[facing];
  const m = materialOf(material), n = to - y + 1, notes = [], air = (x, y, z) => !g.get(x, y, z) || /(^|_)air$/.test(g.get(x, y, z).block);
  if (n < 1) return { steps: 0, landing: null, notes: [`flight: to (${to}) is below the first step (${y})`] };
  for (let i = 0; i < n; i++) for (let w = 0; w < width; w++) {
    const sx = x + dx * i + rx * w, sy = y + i, sz = z + dz * i + rz * w;
    g.set(sx, sy, sz, m.stairs, { facing, half: "bottom", shape: "straight", waterlogged: "false" });
    for (const h of [1, 2]) if (!air(sx, sy + h, sz)) g.set(sx, sy + h, sz, "air");
    if (stringer && i > 0 && air(sx, sy - 1, sz)) g.set(sx, sy - 1, sz, m.stairs, { facing: OPP, half: "top", shape: "straight", waterlogged: "false" });
  }
  const lx = x + dx * n, lz = z + dz * n;
  if (air(lx, to, lz)) notes.push(`flight: nothing to step out onto at ${lx},${to},${lz} (the upper floor should be there)`);
  if (!air(lx, to + 1, lz) || !air(lx, to + 2, lz)) notes.push(`flight: the landing at ${lx},${to + 1},${lz} has no headroom`);
  return { steps: n, landing: [lx, to + 1, lz], notes };
};
/** A chimney stack with its fire inside a crown: at = [x, base y, z] (the shaft's north-west cell), top = the course the
 *  campfire sits in (2+ above the roof it passes), size 1|2. The crown, one wider than the shaft, walls the hay and the
 *  campfire on all four sides and rises one course above the fire, with a slab cap; see chimney.mjs. */
export const chimney = (g, { at: [x, y, z], top, size = 1, material = "bricks", band, fire = true, signal = true }) => {
  const m = materialOf(material), plan = chimneyPlan({ x, z, size, base: y, top, material: m, band: band ? materialOf(band) : m, fire, signal });
  for (const [cx, cy, cz, b, s] of plan) g.set(cx, cy, cz, b, s);
  return plan.length;
};
/** A window shutter: an open trapdoor in the cell in front of the wall (on the face side), lying flat against it.
 *  face: the way the wall looks (north for a north front); the trapdoor's facing is the face, so it lies on the wall. */
export const shutter = (g, [x, y, z], face, wood = "spruce", { height = 1 } = {}) => {
  for (let i = 0; i < height; i++) g.set(x, y + i, z, `${wood}_trapdoor`, { facing: face, half: "bottom", open: "true", powered: "false", waterlogged: "false" });
};
/** A word in banner letters hung on a board, in reading order for its face: bannerWord(g, "BUTCHER", { center: [14, 10, 4], face: "north" }). */
export const bannerWord = (g, word, o) => { let n = 0; for (const [x, y, z, ...b] of bannerWordPlan(word, { ...o, banner: B.banner })) if (!g.get(x, y, z) || /air$/.test(g.get(x, y, z).block)) { g.set(x, y, z, ...b); n++; } return n; };
// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// CHIMNEY STACK: a shaft with a smoking crown. The owner saw campfires perched on the very tip of a stack with a hay
// bale showing beside them. A chimney's fire sits INSIDE the flue: a crown one block wider than the shaft on every side
// covers the hay and the campfire on all four sides, and one more course of masonry rises above the fire, so the smoke
// comes out of a mouth and the fire itself is never seen from the side.
//   chimneyPlan({ x, z, size, base, top, material, band, fire, signal }) -> [[x, y, z, block, state], ...]
//   x, z: the shaft's north-west cell; size: the shaft's width (1 or 2, square); base: its lowest course;
//   top: the course the fire sits in (the crown is top-1 .. top+1, the slab cap at top+2).
//   material / band: { full, slab } (roofs.mjs materialOf). fire: false leaves the flue empty (a dead chimney).
// Layout (size 1, seen from the side):    cap   s s s        top+2: slab cap on the crown ring, the flue open
//                                          rim   # . #        top+1: masonry all round the open flue
//                                          fire  # f #        top  : campfire walled on all four sides
//                                          hay   = h =        top-1: hay walled on all four sides (band course)
//                                          shaft   #          ...  : the shaft, down to base
const AIR = ["air", undefined];

export function chimneyPlan({ x, z, size = 1, base, top, material, band = material, fire = true, signal = true }) {
  const out = [], n = Math.max(1, size), hay = top - 1, rim = top + 1, cap = top + 2;
  const inShaft = (cx, cz) => cx >= x && cx < x + n && cz >= z && cz < z + n;
  const isFlue = (cx, cz) => cx === x && cz === z;               // the fire burns in the north-west shaft cell
  for (let cx = x; cx < x + n; cx++) for (let cz = z; cz < z + n; cz++) for (let y = base; y < hay; y++) out.push([cx, y, cz, material.full, undefined]);
  for (let cx = x - 1; cx <= x + n; cx++) for (let cz = z - 1; cz <= z + n; cz++) {
    const ring = !inShaft(cx, cz);
    for (const y of [hay, top, rim]) {
      if (isFlue(cx, cz) && fire) {
        if (y === hay) out.push([cx, y, cz, signal ? "hay_block" : material.full, signal ? { axis: "y" } : undefined]);
        else if (y === top) out.push([cx, y, cz, "campfire", { lit: "true", signal_fire: String(!!signal), facing: "north", waterlogged: "false" }]);
        else out.push([cx, y, cz, ...AIR]);
      } else if (isFlue(cx, cz) && y !== hay) out.push([cx, y, cz, ...AIR]);
      else out.push([cx, y, cz, y === hay ? band.full : material.full, undefined]);
    }
    if (ring) out.push([cx, cap, cz, material.slab, { type: "bottom", waterlogged: "false" }]);
  }
  return out;
}
export class Grid {
  /** @param {[number,number,number]} size */
  constructor(size, { dataVersion = DATA_VERSIONS["1.21.4"], entities = null } = {}) {
    this.size = [...size];
    this.dataVersion = dataVersion;
    this.entities = entities;                     // typed NBT list, passed through untouched
    /** @type {Map<string, {pos:number[], block:string, state?:Record<string,string>, nbt?:object}>} */
    this.cells = new Map();
  }

  inBounds(x, y, z) {
    return x >= 0 && y >= 0 && z >= 0 && x < this.size[0] && y < this.size[1] && z < this.size[2];
  }

  /** Set one block (state values become strings, as in NBT). Grows nothing: out of bounds throws. */
  set(x, y, z, block, state, nbt) {
    if (!this.inBounds(x, y, z)) throw new Error(`set out of bounds: ${x},${y},${z} (size ${this.size})`);
    const s = state && Object.keys(state).length
      ? Object.fromEntries(Object.entries(state).map(([k, v]) => [k, String(v)])) : undefined;
    this.cells.set(key(x, y, z), { pos: [x, y, z], block: ns(block), ...(s ? { state: s } : {}), ...(nbt ? { nbt } : {}) });
    return this;
  }

  get(x, y, z) { return this.cells.get(key(x, y, z)); }
  blockAt(x, y, z) { return this.get(x, y, z)?.block ?? "minecraft:air"; }
  isAir(x, y, z) { return AIRS.has(this.blockAt(x, y, z)); }
