1	// vocab/h1.mjs: group 1 of plan.md VOCABULARY (lane, piers, window, porch, chimney, table, ham rack, pecan tree,
2	// beehive row). Every helper takes its own position; nothing is hard-wired to a spot.
3	// Writes go into air only (g.isAir). Each helper returns { placed, skipped } and a refused cell is listed in skipped,
4	// never overwritten. The exception is lane_strip, whose footprint IS the surface row it replaces.
5	// Positions plan.md's signatures leave out (y, z, front, facing) come as a trailing options object, defaulted to plan.md.
6	import { chimney } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
7	
8	const LEAF = { persistent: "true", distance: "1", waterlogged: "false" };     // terrain.mjs convention
9	const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
10	
11	const result = () => ({ placed: 0, skipped: [] });
12	
13	/** Air-only write. A cell that already holds a block is recorded in out.skipped and left alone. */
14	function put(g, out, x, y, z, block, state) {
15	  if (!g.isAir(x, y, z)) {
16	    out.skipped.push([x, y, z, block]);
17	    return false;
18	  }
19	  g.set(x, y, z, block, state);
20	  out.placed++;
21	  return true;
22	}
23	
24	/** Lane surface from x0 to x1, five rows from z: coarse_dirt edges, dirt_path ruts, gravel centre (plan SITE).
25	 *  The lane is the surface itself, so it replaces the grass at row y (default 0) and writes nothing under it. */
26	export function lane_strip(g, x0, x1, { z = 0, y = 0 } = {}) {
27	  const out = result();
28	  ["coarse_dirt", "dirt_path", "gravel", "dirt_path", "coarse_dirt"].forEach((block, dz) => {
29	    for (let x = x0; x <= x1; x++) {
30	      g.set(x, y, z + dz, block);
31	      out.placed++;
32	    }
33	  });
34	  return out;
35	}
36	
37	/** Piers on the outline x0,z0..x1,z1: at both ends of every edge and every 3rd cell along it, h courses from row y.
38	 *  The cells between piers get `skirt` (a fence keeps its run along the edge), or stay open when skirt is null. */
39	export function pier_line(g, x0, z0, x1, z1, block, { y = 1, h = 1, skirt = null } = {}) {
40	  const out = result();
41	  const span = (a, b) => {
42	    const p = [];
43	    for (let v = a; v <= b; v += 3) p.push(v);
44	    if (p[p.length - 1] !== b) p.push(b);
45	    return p;
46	  };
47	  const piers = new Set([
48	    ...span(x0, x1).flatMap((x) => [`${x},${z0}`, `${x},${z1}`]),
49	    ...span(z0, z1).flatMap((z) => [`${x0},${z}`, `${x1},${z}`]),
50	  ]);
51	  const outline = [];
52	  for (let x = x0; x <= x1; x++) outline.push([x, z0, "x"], [x, z1, "x"]);
53	  for (let z = z0 + 1; z < z1; z++) outline.push([x0, z, "z"], [x1, z, "z"]);
54	  for (const [x, z, axis] of outline) {
55	    for (let dy = 0; dy < h; dy++) {
56	      if (piers.has(`${x},${z}`)) put(g, out, x, y + dy, z, block);
57	      else if (skirt) {
58	        const state = !skirt.endsWith("_fence") ? undefined
59	          : axis === "x" ? { north: "false", south: "false", east: "true", west: "true" }
60	          : { north: "true", south: "true", east: "false", west: "false" };
61	        put(g, out, x, y + dy, z, skirt, state);
62	      }
63	    }
64	  }
65	  return out;
66	}
67	
68	/** A w x h band of glass panes in a wall that faces `face`. (x, y, z) is the band's lowest cell at its start: the lowest x
69	 *  on a north/south wall, the lowest z on an east/west wall. The panes connect along the wall. `sill` (a material name)
70	 *  lays top slabs one cell out in front of the bottom row; null means no sill. The lintel is the wall's own block, so
71	 *  it is not written here. */
72	export function window(g, x, y, z, face = "north", w = 1, h = 1, { sill = null } = {}) {
73	  const out = result();
74	  const alongX = face === "north" || face === "south";
75	  const [ox, oz] = STEP[face];
76	  const pane = alongX ? { north: "false", south: "false", east: "true", west: "true" }
77	    : { north: "true", south: "true", east: "false", west: "false" };
78	  for (let i = 0; i < w; i++) {
79	    const cx = alongX ? x + i : x, cz = alongX ? z : z + i;
80	    for (let dy = 0; dy < h; dy++) put(g, out, cx, y + dy, cz, "glass_pane", pane);
