98	  for (let x = x0; x <= x1; x++) {
99	    put(g, out, x, 2, z, deck);
100	    put(g, out, x, 2, z + dz, deck);
101	    if (two) {
102	      put(g, out, x, 7, z, deck);
103	      put(g, out, x, 7, z + dz, deck);
104	    }
105	  }
106	  const gapped = (x) => !!gap && x >= gap[0] && x <= gap[1];
107	  const railRow = (y, leaveGap) => {
108	    for (let x = x0; x <= x1; x++) {
109	      if ((leaveGap && gapped(x)) || posts.includes(x)) continue;
110	      const east = x < x1 && !(leaveGap && gapped(x + 1));
111	      const west = x > x0 && !(leaveGap && gapped(x - 1));
112	      put(g, out, x, y, z, rail, { north: "false", south: "false", east: String(east), west: String(west) });
113	    }
114	  };
115	  railRow(3, true);
116	  if (two) railRow(8, false);
117	  if (roof) {
118	    for (let x = x0; x <= x1; x++) {
119	      put(g, out, x, two ? 11 : 6, z, `${roof}_stairs`, { facing: toward, half: "bottom", shape: "straight", waterlogged: "false" });
120	      if (two) put(g, out, x, 11, z + dz, `${roof}_slab`, { type: "top", waterlogged: "false" });
121	      else put(g, out, x, 7, z + dz, `${roof}_slab`, { type: "bottom", waterlogged: "false" });
122	    }
123	  }
124	  return out;
125	}
