127	/** A chimney stack, built by chimney() from the build library: at = [x, base y, z] of the shaft's north-west cell, top =
128	 *  the course its campfire sits in, size 1 or 2. The footing, crown and cap belong to the stack. Writes go through the
129	 *  air-only sink, so anything already standing in the flue or crown is skipped and reported. */
130	export function chimney_stack(g, at, top, size = 1, material = "bricks", band = undefined) {
131	  const out = result();
132	  chimney({ set: (x, y, z, block, state) => put(g, out, x, y, z, block, state) }, { at, top, size, material, band });
133	  return out;
134	}
