136	/** A table: spruce_fence legs at both ends and every 3rd cell, and a spruce_slab top row (type top) one course up,
137	 *  resting on the legs. Footprint: len cells along x at z, rows y and y+1. Nothing is placed at y+2, so the lane past it
138	 *  stays 2 high. */
139	export function table_set(g, x, y, z, len) {
140	  const out = result();
141	  for (let i = 0; i < len; i++) {
142	    if (i === 0 || i === len - 1 || i % 3 === 0) put(g, out, x + i, y, z, "spruce_fence");
143	    put(g, out, x + i, y + 1, z, "spruce_slab", { type: "top", waterlogged: "false" });
144	  }
145	  return out;
146	}
147	
148	/** Hams: a barrel (facing down) hung on an iron_chain at every x in xs and z in zs. The chain is in row y, under the tie
149	 *  beam at y+1 (the beam is not written here); the barrel hangs in row y-1. Footprint: xs x zs, rows y-1..y. */
150	export function ham_rack(g, xs, zs, y) {
